parameters.functionCode:
// Aggregate all QC results
const moderation = $node['OpenAI Moderation'].json;
const brandSafety = JSON.parse($node['Claude Brand Safety'].json.content[0].text);
const plagiarism = $node['Plagiarism Check'].json || { result: { count: 0 } };
const factCheck = JSON.parse($node['Fact Check'].json.choices[0].message.content);

// Calculate overall QC score
let qcScore = 0;
let issues = [];
let passed = true;

// OpenAI Moderation (weight: 30%)
if (!moderation.flagged) {
  qcScore += 0.3;
} else {
  passed = false;
  issues.push('Content flagged by OpenAI moderation');
}

// Brand Safety (weight: 30%)
if (brandSafety.overall_score >= 0.7) {
  qcScore += 0.3 * brandSafety.overall_score;
} else {
  passed = false;
  issues.push(`Brand safety score too low: ${brandSafety.overall_score}`);
}

// Plagiarism (weight: 20%)
if (plagiarism.result && plagiarism.result.count === 0) {
  qcScore += 0.2;
} else if (plagiarism.result && plagiarism.result.count > 0) {
  passed = false;
  issues.push(`Plagiarism detected: ${plagiarism.result.count} matches`);
}

// Fact Check (weight: 20%)
if (factCheck.fact_check_score >= 0.8) {
  qcScore += 0.2 * factCheck.fact_check_score;
} else {
  issues.push(`Fact check concerns: ${factCheck.corrections || 'Review needed'}`);
}

// Platform-specific checks
const platform = items[0].json.platform;
if (platform === 'linkedin' && brandSafety.sentiment && brandSafety.sentiment.professional < 0.6) {
  issues.push('Content not professional enough for LinkedIn');
  qcScore *= 0.8;
}

if (platform === 'tiktok' && items[0].json.content.length > 150) {
  issues.push('Caption too long for TikTok (>150 chars)');
}

return [{
  json: {
    ...items[0].json,
    qc_results: {
      passed: passed && qcScore >= 0.7,
      overall_score: Math.round(qcScore * 100) / 100,
      issues: issues,
      details: {
        moderation: moderation,
        brand_safety: brandSafety,
        plagiarism_matches: plagiarism.result ? plagiarism.result.count : 0,
        fact_check: factCheck
      },
      timestamp: new Date().toISOString()
    }
  }
}];

// Generate improvement suggestions based on QC issues
const qcResults = items[0].json.qc_results;
const suggestions = [];

qcResults.issues.forEach(issue => {
  if (issue.includes('Brand safety')) {
    suggestions.push('Adjust tone to better match brand voice');
  }
  if (issue.includes('Plagiarism')) {
    suggestions.push('Rewrite content to be more original');
  }
  if (issue.includes('Fact check')) {
    suggestions.push('Verify statistics and claims with reliable sources');
  }
  if (issue.includes('too long')) {
    suggestions.push('Shorten content to meet platform limits');
  }
  if (issue.includes('professional')) {
    suggestions.push('Use more formal language and industry terms');
  }
});

return [{
  json: {
    ...items[0].json,
    status: 'needs_revision',
    improvement_suggestions: suggestions,
    retry_with_model: 'claude-sonnet-4' // Suggest better model for revision
  }
}];
